    public void PerformMaintenanceRefuel(Vehicle[] fleet, string fuelType, double amount)
    {
        var fuelService = GetFuelService(fuelType);
        if (fuelService == null)
        {
            Console.WriteLine($"No fuel service available for {fuelType}");
            return;
        }

        Console.WriteLine($"Starting fleet refueling with {fuelType}");
        foreach (var vehicle in fleet)
        {
            if (fuelService.CanService(vehicle.VehicleType))
            {
                fuelService.AddFuel(vehicle, amount);
                Console.WriteLine($"{vehicle.Brand} range: {vehicle.GetRemainingRange()} miles");
            }
            else
            {
                Console.WriteLine($"Cannot refuel {vehicle.Brand} with {fuelType}");
            }
        }
    }

    private IFuelService GetFuelService(string fuelType)
    {
        return fuelServices.FirstOrDefault(service => service.GetFuelType() == fuelType);
    }
}

