    protected var encrypted: Boolean = false

    abstract fun save()
    abstract fun print()
    abstract fun export(targetFormat: String)
    abstract fun compress()

    fun getContent(): String = content
    fun getFormat(): String = format
    fun isEncrypted(): Boolean = encrypted
}

class WordDocument(content: String, private val author: String) : Document(content, "DOCX") {
    private val wordCount = content.split(" ").size

    override fun save() {
        println("Saving Word document with $wordCount words")
    }

    override fun print() {
        println("Printing Word document by $author")
    }

    override fun export(targetFormat: String) {
        println("Exporting Word document to $targetFormat")
    }

    override fun compress() {
        println("Compressing Word document")
    }
}

class SecureDocument(content: String, private val password: String) : Document(content, "SECURE") {
    private var isLocked: Boolean = true

    init {
        encrypted = true
    }

    override fun save() {
        if (isLocked) {
            throw SecurityException("Document is locked and cannot be saved")
        }
        println("Saving secure document")
    }

    override fun print() {
        if (isLocked) {
            throw SecurityException("Document is locked and cannot be printed")
        }
        println("Printing secure document")
    }

    override fun export(targetFormat: String) {
        throw UnsupportedOperationException("Secure documents cannot be exported for security reasons")
    }

    override fun compress() {
        println("Secure documents use built-in compression")
    }

    fun unlock(inputPassword: String) {
        if (password == inputPassword) {
            isLocked = false
            println("Document unlocked")
        } else {
            throw SecurityException("Invalid password")
        }
    }
}

