class ReviewManagementService {
    private EmailService emailService;
    private DatabaseService dbService;
    private EmailContentService emailContentService;

    public ReviewManagementService() {
        this.emailService = new EmailService("smtp.bookstore.com");
        this.dbService = new DatabaseService("jdbc:mysql://localhost:3306/bookstore");
        this.emailContentService = new EmailContentService();
    }

    public void processCustomerReview(Book book, String customerEmail, String review, double rating) {
        ValidationService validator = new ValidationService();
        if (validator.validateRating(rating)) {
            book.getReviews().add(review);
            book.getCustomerEmails().add(customerEmail);
            book.setAverageRating(recalculateRatingMetrics(book.getAverageRating(), book.getReviews().size(), rating));
            sendReviewConfirmationEmail(book, customerEmail);
            logReviewActivity(book.getIsbn(), customerEmail, rating);
        }
    }

    private double recalculateRatingMetrics(double currentAverage, int reviewCount, double newRating) {
        return reviewCount == 1 ? newRating : (currentAverage * (reviewCount - 1) + newRating) / reviewCount;
    }

    private void sendReviewConfirmationEmail(Book book, String customerEmail) {
        String subject = "Thank you for reviewing: " + book.getTitle();
        String body = emailContentService.createReviewThankYouEmail(book.getTitle(), book.getAuthor());
        emailService.sendEmail(customerEmail, subject, body);
    }

    private void logReviewActivity(String isbn, String customerEmail, double rating) {
        String logDetails = "Review added - Book: " + isbn + ", Customer: " + customerEmail + ", Rating: " + rating;
        dbService.logTransaction("REVIEW_ADDED", logDetails);
    }
}

class SalesManagementService {
    private DatabaseService dbService;
    private EmailService emailService;
    private EmailContentService emailContentService;
    private InventoryManagementService inventoryService;

    public SalesManagementService() {
        this.dbService = new DatabaseService("jdbc:mysql://localhost:3306/bookstore");
        this.emailService = new EmailService("smtp.bookstore.com");
        this.emailContentService = new EmailContentService();
        this.inventoryService = new InventoryManagementService();
    }

    public void processSaleTransaction(Book book, String customerEmail) {
        book.setTotalSales(book.getTotalSales() + 1);
        book.getCustomerEmails().add(customerEmail);

        inventoryService.updateInventoryStatus(book);

        dbService.updateSalesData(book.getIsbn(), book.getTotalSales());

        String receiptEmail = emailContentService.generateSalesReceiptEmail(book);
        emailService.sendEmail(customerEmail, "Purchase Confirmation - " + book.getTitle(), receiptEmail);

        logSalesTransaction(book, customerEmail);

        if (book.getTotalSales() % 100 == 0) {
            sendMilestoneNotification(book);
        }
    }

    private void logSalesTransaction(Book book, String customerEmail) {
        PricingService pricingService = new PricingService();
        double finalPrice = pricingService.calculateFinalPrice(book.getPrice(), book.getDiscountRate());
        String logDetails = "Sale completed - Book: " + book.getIsbn() + ", Customer: " + customerEmail + ", Price: $" + finalPrice;
        dbService.logTransaction("SALE_COMPLETED", logDetails);
    }

    private void sendMilestoneNotification(Book book) {
        String subject = "Sales Milestone Reached: " + book.getTitle();
        String body = "Congratulations! '" + book.getTitle() + "' has reached " + book.getTotalSales() + " sales!";
        emailService.sendEmail("sales@bookstore.com", subject, body);
    }
}

class PricingService {
    public double calculateFinalPrice(double price, double discountRate) {
        return price * (1.0 - discountRate);
    }

    public double calculateAuthorRoyalty(int totalSales, double finalPrice) {
        double baseRate = 0.10;
        if (totalSales > 5000) baseRate = 0.18;
        else if (totalSales > 1000) baseRate = 0.15;
        return totalSales * finalPrice * baseRate;
    }
}

class InventoryManagementService {
    public void updateInventoryStatus(Book book) {
        if (book.getTotalSales() > 1000) {
            book.setAvailable(Math.random() > 0.1);
        }
