class SalesProcessingService:
    def __init__(self):
        self.payment_processor = PaymentProcessor("pay_api_key_123")
        self.shipping_service = ShippingService("FedEx")
        self.database = InventoryDatabase("jdbc:mysql://localhost:3306/inventory")
        self.email_service = EmailService("smtp.ecommerce.com")
        self.analytics = AnalyticsService("analytics_key_456")
        self.pricing_service = PricingCalculationService()
        self.email_content_service = EmailContentService()
        self.stock_alert_service = StockAlertService()

    def process_complex_sale(self, product, quantity, customer_email, shipping_address, region, card_number):
        if product.get_stock_quantity() < quantity:
            return "FAILED: Insufficient stock"

        unit_price = self.pricing_service.calculate_dynamic_pricing(product.get_price(), product.get_total_sales(), product.get_stock_quantity(), product.get_discount_rate())
        discount = self.pricing_service.calculate_tiered_discount(quantity)
        subtotal = unit_price * quantity * (1 - discount)
        shipping_cost = self.shipping_service.calculate_shipping_rate(region, product.get_weight() * quantity)
        total_amount = subtotal + shipping_cost

        if not self.payment_processor.process_payment(total_amount, card_number):
            return "FAILED: Payment declined"

        product.set_stock_quantity(product.get_stock_quantity() - quantity)
        product.set_total_sales(product.get_total_sales() + quantity)
        product.get_sales_by_region()[region] = product.get_sales_by_region().get(region, 0) + quantity

        tracking_number = self.shipping_service.create_shipment(shipping_address, product.get_weight() * quantity)

        self.database.update_stock(product.get_product_id(), product.get_stock_quantity())

        receipt_email = self.email_content_service.generate_advanced_receipt(product.get_name(), product.get_product_id(), quantity, unit_price, discount, shipping_cost, total_amount, tracking_number)
        self.email_service.send_email(customer_email, f"Order Confirmation - {product.get_name()}", receipt_email)

        self.stock_alert_service.check_advanced_stock_alerts(product, self.email_service, self.analytics)

        sale_data = {
            "quantity": str(quantity),
            "amount": str(total_amount),
            "region": region
        }
        self.analytics.track_event("SALE_COMPLETED", product.get_product_id(), sale_data)

        self.database.log_transaction("COMPLEX_SALE", f"Product: {product.get_product_id()}, Qty: {quantity}, Amount: ${total_amount}, Region: {region}")

        return f"SUCCESS: Order placed - Tracking: {tracking_number}"


