class ISBNGenerationService {
    fun generateISBN(): String {
        val timestamp = System.currentTimeMillis() % 10000
        val randomNum = Random.nextInt(1000)
        return "978-$timestamp-${String.format("%03d", randomNum)}"
    }
}

class PageCalculationService {
    fun calculatePageCount(content: String): Int {
        return if (content.isNotEmpty()) maxOf(1, content.length / 250) else 1
    }
}

class ValidationService {
    fun validateISBN(isbn: String): Boolean {
        if (isbn.length < 10) return false
        val cleanISBN = isbn.replace(Regex("[^0-9X]"), "")
        return cleanISBN.length == 10 || cleanISBN.length == 13
    }

    fun validatePrice(price: Double): Boolean {
        return price >= 0.0 && price <= 999.99
    }

    fun validateRating(rating: Double): Boolean {
        return rating in 1.0..5.0
    }
}

class ReviewManagementService {
    private val validator = ValidationService()

    fun addReview(book: Book, review: String, rating: Double) {
        if (validator.validateRating(rating)) {
            book.getReviews().add(review)
            book.setAverageRating(calculateNewAverageRating(book.getAverageRating(), book.getReviews().size, rating))
            println("Review added successfully")
        } else {
            println("Invalid rating. Must be between 1.0 and 5.0")
        }
    }

    private fun calculateNewAverageRating(currentAverage: Double, reviewCount: Int, newRating: Double): Double {
        return if (reviewCount == 1) {
            newRating
        } else {
            (currentAverage * (reviewCount - 1) + newRating) / reviewCount
        }
    }
}

