        val bonus = salaryService.calculatePerformanceBonus(employee.baseSalary, employee.performanceRating, employee.yearsOfService)
        val overtime = salaryService.calculateOvertimeCompensation(employee.baseSalary, employee.overtimeHours)
        val gross = salary + bonus + overtime
        val federalTax = taxService.calculateFederalTax(gross)
        val stateTax = taxService.calculateStateTax(gross)
        val ssTax = taxService.calculateSocialSecurityTax(gross)
        val totalTax = federalTax + stateTax + ssTax
        val netPay = gross - totalTax

        return buildString {
            appendLine("=== COMPENSATION BREAKDOWN ===")
            appendLine("Base Salary: $${String.format("%.2f", salary)}")
            appendLine("Performance Bonus: $${String.format("%.2f", bonus)}")
            appendLine("Overtime Pay: $${String.format("%.2f", overtime)}")
            appendLine("Gross Pay: $${String.format("%.2f", gross)}")
