            product.customerEmails.add(customerEmail)
            product.averageRating = recalculateAdvancedRating(product.averageRating, product.customerReviews.size, rating)

            val thankYouEmail = emailContentService.createReviewThankYouEmail(product.name, customerEmail, rating)
            emailService.sendEmail(customerEmail, "Thank you for your review!", thankYouEmail)

            val analyticsData = mapOf(
                "rating" to rating.toString(),
                "region" to region
            )
            analytics.trackEvent("REVIEW_ADDED", product.productId, analyticsData)

            database.logTransaction("REVIEW_PROCESSED", "Product: ${product.productId}, Rating: $rating, Region: $region")

            if (product.averageRating >= 4.5 && product.customerReviews.size >= 10) {
                triggerBestSellerPromotion(product)
            }
        }
    }

    private fun recalculateAdvancedRating(currentAverage: Double, reviewCount: Int, newRating: Double): Double {
        return if (reviewCount == 1) newRating else (currentAverage * (reviewCount - 1) + newRating) / reviewCount
    }

    private fun triggerBestSellerPromotion(product: Product) {
        val promoEmail = "BESTSELLER ALERT: ${product.name} is now a top-rated product with ${product.averageRating} stars!"
        emailService.sendBulkEmail(product.customerEmails, "Special Offer on Bestseller", promoEmail)
        analytics.trackEvent("BESTSELLER_PROMOTION", product.productId, emptyMap())
    }
}

class SalesProcessingService {
    private val paymentProcessor = PaymentProcessor("pay_api_key_123")
    private val shippingService = ShippingService("FedEx")
    private val database = InventoryDatabase("jdbc:mysql://localhost:3306/inventory")
    private val emailService = EmailService("smtp.ecommerce.com")
    private val analytics = AnalyticsService("analytics_key_456")
    private val pricingService = PricingCalculationService()
    private val emailContentService = EmailContentService()
    private val stockAlertService = StockAlertService()

    fun processComplexSale(product: Product, quantity: Int, customerEmail: String, shippingAddress: String, region: String, cardNumber: String): String {
        if (product.stockQuantity < quantity) {
            return "FAILED: Insufficient stock"
        }

        val unitPrice = pricingService.calculateDynamicPricing(product.price, product.totalSales, product.stockQuantity, product.discountRate)
        val discount = pricingService.calculateTieredDiscount(quantity)
        val subtotal = unitPrice * quantity * (1 - discount)
        val shippingCost = shippingService.calculateShippingRate(region, product.weight * quantity)
        val totalAmount = subtotal + shippingCost

        if (!paymentProcessor.processPayment(totalAmount, cardNumber)) {
            return "FAILED: Payment declined"
        }

        product.stockQuantity -= quantity
        product.totalSales += quantity
        product.salesByRegion[region] = product.salesByRegion.getOrDefault(region, 0) + quantity

        val trackingNumber = shippingService.createShipment(shippingAddress, product.weight * quantity)

        database.updateStock(product.productId, product.stockQuantity)

        val receiptEmail = emailContentService.generateAdvancedReceipt(product.name, product.productId, quantity, unitPrice, discount, shippingCost, totalAmount, trackingNumber)
        emailService.sendEmail(customerEmail, "Order Confirmation - ${product.name}", receiptEmail)

        stockAlertService.checkAdvancedStockAlerts(product, emailService, analytics)

        val saleData = mapOf(
            "quantity" to quantity.toString(),
            "amount" to totalAmount.toString(),
            "region" to region
        )
        analytics.trackEvent("SALE_COMPLETED", product.productId, saleData)

        database.logTransaction("COMPLEX_SALE", "Product: ${product.productId}, Qty: $quantity, Amount: $$totalAmount, Region: $region")

        return "SUCCESS: Order placed - Tracking: $trackingNumber"
    }
}

class StockAlertService {
    fun checkAdvancedStockAlerts(product: Product, emailService: EmailService, analytics: AnalyticsService) {
        when {
            product.stockQuantity <= 5 -> {
                val urgentAlert = "URGENT: Product ${product.name} (${product.productId}) critically low - Only ${product.stockQuantity} units left!"
                emailService.sendEmail("urgent@company.com", "Critical Stock Alert", urgentAlert)
                analytics.trackEvent("CRITICAL_STOCK_ALERT", product.productId, emptyMap())
            }
            product.stockQuantity <= 20 -> {
                val alert = "LOW STOCK: Product ${product.name} has ${product.stockQuantity} units remaining."
                emailService.sendEmail("inventory@company.com", "Low Stock Alert", alert)
            }
        }
    }
}

class InventoryManagementService {
    private val database = InventoryDatabase("jdbc:mysql://localhost:3306/inventory")
    private val emailService = EmailService("smtp.ecommerce.com")
    private val analytics = AnalyticsService("analytics_key_456")
    private val emailContentService = EmailContentService()

    fun executeSmartRestock(product: Product, supplierEmail: String) {
        val recommendedStock = calculateOptimalStockLevel(product.totalSales)
        val restockQuantity = recommendedStock - product.stockQuantity

        if (restockQuantity > 0) {
            product.stockQuantity += restockQuantity
            database.updateStock(product.productId, product.stockQuantity)

            val restockEmail = emailContentService.generateSmartRestockEmail(product.name, product.productId, restockQuantity, product.stockQuantity, recommendedStock, product.totalSales)
            emailService.sendEmail(supplierEmail, "Smart Restock Completed - ${product.name}", restockEmail)

            analytics.trackEvent("SMART_RESTOCK", product.productId, mapOf("quantity" to restockQuantity.toString()))
            database.logTransaction("SMART_RESTOCK", "Product: ${product.productId}, Added: $restockQuantity, Target: $recommendedStock")
        }
    }

    private fun calculateOptimalStockLevel(totalSales: Int): Int {
        val averageMonthlySales = totalSales / maxOf(1, java.time.LocalDate.now().monthValue)
        val seasonalFactor = if (java.time.LocalDate.now().monthValue == 12) 2 else 1
        return averageMonthlySales * 2 * seasonalFactor
    }
}

