        {
            _smsService.SendSMS(PhoneNumber, $"Security Alert: {message}");
        }
    }

    public void AddToLoginHistory(string entry)
    {
        string timestampedEntry = $"{DateTime.Now}: {entry}";
        LoginHistory.Add(timestampedEntry);
        if (LoginHistory.Count > 100)
        {
            LoginHistory.RemoveAt(0);
        }
    }

    private void InitializeDefaultPreferences()
    {
        Preferences["theme"] = "light";
        Preferences["language"] = "en";
        Preferences["notifications"] = "enabled";
    }

    public void UpdatePreference(string key, string value)
    {
        string oldValue = Preferences.ContainsKey(key) ? Preferences[key] : null;
        Preferences[key] = value;
        LogPreferenceChange(key, oldValue, value);
