    public bool Authenticate(User user, string password)
    {
        if (user.LoginAttempts >= 5)
        {
            Console.WriteLine("Account locked due to too many failed attempts");
            return false;
        }

        if (user.Password != null && _passwordService.VerifyPassword(password, user.Password))
        {
            user.ResetLoginAttempts();
            user.UpdateLastLogin();
            user.AddToLoginHistory("Successful login from IP: 192.168.1.100");
