public class SalaryCalculationService
{
    public double CalculateBaseSalary(double baseSalary, int yearsOfService)
    {
        return baseSalary + (yearsOfService * 1000);
    }

    public double CalculatePerformanceBonus(double baseSalary, double performanceRating, int yearsOfService)
    {
        double baseBonus = baseSalary * 0.12;
        double ratingMultiplier = performanceRating / 5.0;
        double serviceMultiplier = Math.Min(yearsOfService * 0.02, 0.15);
        return baseBonus * ratingMultiplier * (1.0 + serviceMultiplier);
    }

    public double CalculateOvertimeCompensation(double baseSalary, double overtimeHours)
    {
        if (overtimeHours > 0)
        {
            double hourlyRate = baseSalary / (52 * 40);
            return overtimeHours * hourlyRate * 1.5;
        }
        return 0.0;
    }

    public double CalculateTotalCompensation(double baseSalary, int yearsOfService, double performanceRating, double overtimeHours)
    {
        double salary = CalculateBaseSalary(baseSalary, yearsOfService);
        double bonus = CalculatePerformanceBonus(baseSalary, performanceRating, yearsOfService);
        double overtime = CalculateOvertimeCompensation(baseSalary, overtimeHours);
        return salary + bonus + overtime;
    }
}

public class TaxCalculationService
{
    public double CalculateFederalTax(double grossPay)
    {
        if (grossPay <= 4000) return grossPay * 0.18;
        else if (grossPay <= 8000) return grossPay * 0.22;
        else return grossPay * 0.28;
    }

    public double CalculateStateTax(double grossPay)
    {
        return grossPay * 0.085;
    }

    public double CalculateSocialSecurityTax(double grossPay)
    {
        return Math.Min(grossPay * 0.062, 8853.60);
    }

    public double CalculateTotalTax(double grossPay)
    {
        return CalculateFederalTax(grossPay) + CalculateStateTax(grossPay) + CalculateSocialSecurityTax(grossPay);
    }
}

