public class ReportGenerationService
{
    public string GenerateCompensationBreakdown(Employee employee, SalaryCalculationService salaryService, TaxCalculationService taxService)
    {
        double salary = salaryService.CalculateBaseSalary(employee.BaseSalary, employee.YearsOfService);
        double bonus = salaryService.CalculatePerformanceBonus(employee.BaseSalary, employee.PerformanceRating, employee.YearsOfService);
        double overtime = salaryService.CalculateOvertimeCompensation(employee.BaseSalary, employee.OvertimeHours);
        double gross = salary + bonus + overtime;
        double federalTax = taxService.CalculateFederalTax(gross);
        double stateTax = taxService.CalculateStateTax(gross);
        double ssTax = taxService.CalculateSocialSecurityTax(gross);
        double totalTax = federalTax + stateTax + ssTax;
        double netPay = gross - totalTax;

        var breakdown = new StringBuilder();
        breakdown.AppendLine("=== COMPENSATION BREAKDOWN ===");
        breakdown.AppendLine($"Base Salary: ${salary:F2}");
        breakdown.AppendLine($"Performance Bonus: ${bonus:F2}");
        breakdown.AppendLine($"Overtime Pay: ${overtime:F2}");
        breakdown.AppendLine($"Gross Pay: ${gross:F2}");
        breakdown.AppendLine($"Federal Tax: ${federalTax:F2}");
        breakdown.AppendLine($"State Tax: ${stateTax:F2}");
        breakdown.AppendLine($"Social Security: ${ssTax:F2}");
        breakdown.Append($"Net Pay: ${netPay:F2}");
