        public void GenerateUniqueISBN()
        {
            long timestamp = DateTimeOffset.Now.ToUnixTimeMilliseconds();
            string category = (Genre != null && Genre.Equals("fiction")) ? "FIC" : "NF";
            Random random = new Random();
            ISBN = $"978-{category}-{timestamp % 100000}-{random.Next(100):D2}";
        }

        public void CalculateDynamicPageCount()
        {
            if (!string.IsNullOrEmpty(Content))
            {
                int basePages = Content.Length / 250;
                double formatMultiplier = Format.Equals("hardcover") ? 1.2 : 1.0;
                PageCount = Math.Max(1, (int)(basePages * formatMultiplier));
