    public interface IISBNGenerationService
    {
        string GenerateUniqueISBN(string genre);
    }

    public class ISBNGenerationService : IISBNGenerationService
    {
        public string GenerateUniqueISBN(string genre)
        {
            long timestamp = DateTimeOffset.Now.ToUnixTimeMilliseconds();
            string category = (genre != null && genre.Equals("fiction")) ? "FIC" : "NF";
            Random random = new Random();
            return $"978-{category}-{timestamp % 100000}-{random.Next(100):D2}";
        }
    }

    public interface IPageCalculationService
    {
        int CalculateDynamicPageCount(string content, string format);
    }

    public class PageCalculationService : IPageCalculationService
    {
        public int CalculateDynamicPageCount(string content, string format)
        {
            if (!string.IsNullOrEmpty(content))
            {
                int basePages = content.Length / 250;
                double formatMultiplier = (format != null && format.Equals("hardcover")) ? 1.2 : 1.0;
                return Math.Max(1, (int)(basePages * formatMultiplier));
            }
            return 1;
        }
    }

    public interface IValidationService
    {
        bool ValidateCompleteBookData(string title, string author, string isbn, double price, string content);
        bool ValidateISBNFormat(string isbn);
        bool ValidatePriceRange(double price);
        bool ValidateRating(double rating);
        bool ValidateDiscountRate(double discountPercentage);
    }

    public class ValidationService : IValidationService
    {
        public bool ValidateCompleteBookData(string title, string author, string isbn, double price, string content)
        {
            return !string.IsNullOrWhiteSpace(title) &&
                   !string.IsNullOrWhiteSpace(author) &&
                   ValidateISBNFormat(isbn) &&
                   ValidatePriceRange(price) &&
                   !string.IsNullOrEmpty(content);
        }

        public bool ValidateISBNFormat(string isbn)
        {
            if (string.IsNullOrEmpty(isbn)) return false;
            string clean = Regex.Replace(isbn, "[^0-9X]", "");
            return clean.Length == 10 || clean.Length == 13;
        }

        public bool ValidatePriceRange(double price)
        {
            return price >= 0.99 && price <= 999.99;
        }

        public bool ValidateRating(double rating)
        {
            return rating >= 1.0 && rating <= 5.0;
        }

        public bool ValidateDiscountRate(double discountPercentage)
        {
            return discountPercentage >= 0.0 && discountPercentage <= 0.5;
        }
    }

    public interface IReviewManagementService
    {
        void ProcessCustomerReview(Book book, string customerEmail, string review, double rating);
    }

    public class ReviewManagementService : IReviewManagementService
    {
        private readonly EmailService emailService;
        private readonly DatabaseService dbService;
        private readonly IEmailContentService emailContentService;
        private readonly IValidationService validationService;

        public ReviewManagementService()
        {
            emailService = new EmailService("smtp.bookstore.com");
            dbService = new DatabaseService("Server=localhost;Database=bookstore;Integrated Security=true;");
            emailContentService = new EmailContentService();
            validationService = new ValidationService();
        }

        public void ProcessCustomerReview(Book book, string customerEmail, string review, double rating)
        {
            if (validationService.ValidateRating(rating))
            {
                book.Reviews.Add(review);
                book.CustomerEmails.Add(customerEmail);
                book.AverageRating = RecalculateRatingMetrics(book.AverageRating, book.Reviews.Count, rating);
                SendReviewConfirmationEmail(book, customerEmail);
                LogReviewActivity(book.ISBN, customerEmail, rating);
            }
        }

        private double RecalculateRatingMetrics(double currentAverage, int reviewCount, double newRating)
        {
            return reviewCount == 1 ? newRating : (currentAverage * (reviewCount - 1) + newRating) / reviewCount;
        }

        private void SendReviewConfirmationEmail(Book book, string customerEmail)
        {
            string subject = $"Thank you for reviewing: {book.Title}";
            string body = emailContentService.CreateReviewThankYouEmail(book.Title, book.Author);
            emailService.SendEmail(customerEmail, subject, body);
        }

        private void LogReviewActivity(string isbn, string customerEmail, double rating)
        {
            string logDetails = $"Review added - Book: {isbn}, Customer: {customerEmail}, Rating: {rating}";
            dbService.LogTransaction("REVIEW_ADDED", logDetails);
        }
    }

    public interface ISalesManagementService
    {
        void ProcessSaleTransaction(Book book, string customerEmail);
    }

    public class SalesManagementService : ISalesManagementService
