        private readonly EmailService emailService;
        private readonly IEmailContentService emailContentService;
        private readonly IInventoryManagementService inventoryService;

        public SalesManagementService()
        {
            dbService = new DatabaseService("Server=localhost;Database=bookstore;Integrated Security=true;");
            emailService = new EmailService("smtp.bookstore.com");
            emailContentService = new EmailContentService();
            inventoryService = new InventoryManagementService();
        }

        public void ProcessSaleTransaction(Book book, string customerEmail)
        {
            book.TotalSales++;
            book.CustomerEmails.Add(customerEmail);

            inventoryService.UpdateInventoryStatus(book);

            dbService.UpdateSalesData(book.ISBN, book.TotalSales);

            string receiptEmail = emailContentService.GenerateSalesReceiptEmail(book);
            emailService.SendEmail(customerEmail, $"Purchase Confirmation - {book.Title}", receiptEmail);

            LogSalesTransaction(book, customerEmail);

            if (book.TotalSales % 100 == 0)
            {
                SendMilestoneNotification(book);
            }
        }

        private void LogSalesTransaction(Book book, string customerEmail)
        {
            var pricingService = new PricingService();
            double finalPrice = pricingService.CalculateFinalPrice(book.Price, book.DiscountRate);
            string logDetails = $"Sale completed - Book: {book.ISBN}, Customer: {customerEmail}, Price: ${finalPrice}";
            dbService.LogTransaction("SALE_COMPLETED", logDetails);
        }

        private void SendMilestoneNotification(Book book)
        {
            string subject = $"Sales Milestone Reached: {book.Title}";
            string body = $"Congratulations! '{book.Title}' has reached {book.TotalSales} sales!";
            emailService.SendEmail("sales@bookstore.com", subject, body);
        }
    }

    public interface IPricingService
    {
        double CalculateFinalPrice(double price, double discountRate);
        double CalculateAuthorRoyalty(int totalSales, double finalPrice);
    }

    public class PricingService : IPricingService
    {
        public double CalculateFinalPrice(double price, double discountRate)
        {
            return price * (1.0 - discountRate);
        }

        public double CalculateAuthorRoyalty(int totalSales, double finalPrice)
        {
            double baseRate = totalSales switch
            {
                > 5000 => 0.18,
                > 1000 => 0.15,
                _ => 0.10
            };
            return totalSales * finalPrice * baseRate;
        }
    }

    public interface IInventoryManagementService
    {
        void UpdateInventoryStatus(Book book);
    }

    public class InventoryManagementService : IInventoryManagementService
    {
