            InitializeBookDefaults();
        }

        private void InitializeBookDefaults()
        {
            var isbnService = new ISBNGenerationService();
            _isbn = isbnService.GenerateUniqueISBN(_genre);

            UpdatePageCount();

            _genre = "general";
            _price = 19.99;
            Publisher = "Independent Press";
        }

        private void UpdatePageCount()
        {
            var pageService = new PageCalculationService();
            _pageCount = pageService.CalculateDynamicPageCount(Content, _format);
        }

        public void SetContent(string content)
        {
            Content = content;
            UpdatePageCount();
        }

        public void SetPrice(double price)
        {
            var validator = new ValidationService();
            if (validator.ValidatePriceRange(price))
            {
                _price = price;
            }
        }

