        public double CalculateFinalPrice()
        {
            var pricingService = new PricingService();
            return pricingService.CalculateFinalPrice(_price, DiscountRate);
        }

        public double CalculateAuthorRoyalty()
        {
            var pricingService = new PricingService();
            return pricingService.CalculateAuthorRoyalty(TotalSales, CalculateFinalPrice());
        }

        public bool ValidateData()
        {
            var validator = new ValidationService();
            return validator.ValidateCompleteBookData(Title, Author, _isbn, _price, Content);
        }
    }
