class AnalyticsReportingService
{
    private PricingCalculationService pricingService;

    public AnalyticsReportingService()
    {
        this.pricingService = new PricingCalculationService();
    }

    public string GenerateComprehensiveAnalytics(Product product)
    {
        double currentPrice = pricingService.CalculateDynamicPricing(product.Price, product.TotalSales, product.StockQuantity, product.DiscountRate);
        double totalRevenue = product.TotalSales * currentPrice;
        double profitMargin = pricingService.CalculateComplexProfitMargin(product.Price, product.TotalSales, product.StockQuantity, product.DiscountRate, product.CostPrice, product.Weight);
        string topRegion = product.SalesByRegion.Count > 0 ? product.SalesByRegion.OrderByDescending(x => x.Value).First().Key : "N/A";

        return $"COMPREHENSIVE ANALYTICS\n" +
               $"Product: {product.Name} ({product.ProductId})\n" +
               $"Total Sales: {product.TotalSales} units\n" +
               $"Revenue: ${totalRevenue:F2}\n" +
               $"Profit Margin: {profitMargin:F2}%\n" +
               $"Average Rating: {product.AverageRating:F2} ({product.CustomerReviews.Count} reviews)\n" +
               $"Top Region: {topRegion}\n" +
               $"Stock Level: {product.StockQuantity}\n" +
               $"Current Price: ${currentPrice:F2}";
    }
}

