    public void LaunchMarketingCampaign(Product product, string campaignType)
    {
        string campaignEmail = emailContentService.CreateCampaignEmail(product.Name, campaignType);
        emailService.SendBulkEmail(product.CustomerEmails, $"Special Campaign - {product.Name}", campaignEmail);

        Dictionary<string, string> campaignData = new Dictionary<string, string>
        {
            ["type"] = campaignType,
            ["reach"] = product.CustomerEmails.Count.ToString()
        };
        analytics.TrackEvent("MARKETING_CAMPAIGN", product.ProductId, campaignData);

        database.LogTransaction("CAMPAIGN_LAUNCHED", $"Product: {product.ProductId}, Type: {campaignType}, Reach: {product.CustomerEmails.Count}");
