        this.SalesByRegion["Europe"] = 0;
        this.SalesByRegion["Asia"] = 0;

        ProductIdGenerationService idService = new ProductIdGenerationService();
        this.ProductId = idService.GenerateAdvancedProductId(this.Name, this.Category);
    }
}

